import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Craft Queue","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/station/queue.md","filePath":"en/modules/station/queue.md","lastUpdated":0}`),a={name:`en/modules/station/queue.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="craft-queue" tabindex="-1">Craft Queue <a class="header-anchor" href="#craft-queue" aria-label="Permalink to “Craft Queue”">​</a></h1><p>One player owns one queue per station. The queue is <strong>serial and single-line</strong>: only the head advances while later entries wait.</p><h2 id="entry-states" tabindex="-1">Entry States <a class="header-anchor" href="#entry-states" aria-label="Permalink to “Entry States”">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Occupies queue length</th><th>Description</th></tr></thead><tbody><tr><td><code>WAITING</code></td><td>Yes</td><td>Submitted and waiting in line.</td></tr><tr><td><code>RUNNING</code></td><td>Yes</td><td>At the head, advancing its duration.</td></tr><tr><td><code>PENDING_CLAIM</code></td><td>No</td><td>Finished, but the output could not be delivered; waiting to be claimed.</td></tr></tbody></table><p><code>PENDING_CLAIM</code> deliberately does not occupy queue length: otherwise a player whose warehouse and inventory are both full would be deadlocked by their own undelivered output and unable to queue anything. Pending claims are bounded by their own ceiling, <code>limits.max_pending_claim</code>, which defaults to 100.</p><h2 id="the-three-sources-of-queue-length" tabindex="-1">The Three Sources of Queue Length <a class="header-anchor" href="#the-three-sources-of-queue-length" aria-label="Permalink to “The Three Sources of Queue Length”">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Relation to base length</th><th>Configured in</th></tr></thead><tbody><tr><td>Base length</td><td>The starting point</td><td><code>queue.base_length</code> in <code>config.yml</code>, overridable per station.</td></tr><tr><td>Permission tier</td><td><strong>Replaces</strong> it</td><td><code>emakistation.queue.&lt;n&gt;</code>, requires <code>queue.permission_tiers: true</code>.</td></tr><tr><td>Paid purchase</td><td><strong>Stacks</strong> on top</td><td>Bought on the queue page, see <a href="./queue-costs.html">Paid Queue Slots</a>.</td></tr></tbody></table><p>The highest numbered tier wins; with no such permission the base length is kept. Purchased slots stack on top of the effective tier, and the result is clamped by <code>queue.max_length</code>.</p><p>Tiers replace while purchases stack so that granting a player a tier afterwards does not swallow the slots they paid for.</p><h2 id="progression" tabindex="-1">Progression <a class="header-anchor" href="#progression" aria-label="Permalink to “Progression”">​</a></h2><p><code>queue.progress_mode</code> decides how the head is timed:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>offline</code></td><td>Follows real time; the timer keeps running while the player is offline.</td></tr><tr><td><code>online</code></td><td>Only accumulates while the player is online.</td></tr></tbody></table><p><code>offline</code> only means &quot;the timer keeps running&quot;, not &quot;delivery while offline&quot;. EmakiStorage refuses any write for an offline player, so entries that come due while offline are merely &quot;due&quot;; settlement happens at the next login.</p><p>There is exactly one server-wide advance timer, controlled by <code>queue.tick_interval</code> (default 20 ticks), not one timer per queue.</p><h2 id="duration" tabindex="-1">Duration <a class="header-anchor" href="#duration" aria-label="Permalink to “Duration”">​</a></h2><p>A single craft&#39;s duration comes from the recipe&#39;s <code>duration_seconds</code>, multiplied by the station-level or global <code>speed_multiplier</code>. A <code>duration_seconds</code> of <code>0</code> or omitted completes immediately without entering the queue.</p><h2 id="cancellation-and-refunds" tabindex="-1">Cancellation and Refunds <a class="header-anchor" href="#cancellation-and-refunds" aria-label="Permalink to “Cancellation and Refunds”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation cancel &lt;station&gt; &lt;index&gt;</span></span></code></pre></div><p>Indexes in commands and in the window start at <strong>1</strong> (the API&#39;s <code>index</code> parameter starts at 0).</p><p>The refund fraction comes from the station&#39;s <code>queue.cancel_refund_rate</code>, applied identically to materials and to any currency already paid. Refunds always return <strong>to the channel each material came from</strong>, independent of the station&#39;s output routing.</p><p>Refunds are not prorated by progress. In a serial single-line queue only the head has progress, and per-entry progress accounting for an almost non-existent case is not worth it. This is an intentional simplification.</p><p>A partial refund still reports success and carries the shortfall as a <code>Partial</code> reason key.</p><p>Entries in the <code>PENDING_CLAIM</code> state cannot be cancelled; the attempt is refused with <code>station.cancel_pending_claim</code>.</p><h2 id="claiming-outputs" tabindex="-1">Claiming Outputs <a class="header-anchor" href="#claiming-outputs" aria-label="Permalink to “Claiming Outputs”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation claim</span></span></code></pre></div><p>One call claims every deliverable pending output the player owns <strong>across all stations</strong>. Entries that still cannot be delivered stay pending instead of failing the whole call, so this command is safe to run unconditionally.</p><h2 id="administrative-operations" tabindex="-1">Administrative Operations <a class="header-anchor" href="#administrative-operations" aria-label="Permalink to “Administrative Operations”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation admin queue &lt;...&gt;</span></span></code></pre></div><p>Requires <code>emakistation.admin</code>.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};